    pub const fn name(self) -> &'static str { Self::NAMES[self as usize] }
    pub fn from_name(name: &str) -> Option<LimitId> { Self::ALL.into_iter().find(|member| member.name() == name) }
    pub const fn to_wire(self) -> u32 { self as u32 }
    pub const fn from_wire(word: u32) -> Option<LimitId> { if (word as usize) < Self::COUNT { Some(Self::ALL[word as usize]) } else { None } }
    pub const fn stage(self) -> Stage { Self::STAGE[self as usize] }
    pub const fn protects(self) -> Protects { Self::PROTECTS[self as usize] }
    pub const fn degrades_to(self) -> DegradesTo { Self::DEGRADES_TO[self as usize] }
    pub const fn value_on_arm64(self) -> u64 { Self::VALUE_ON_ARM64[self as usize] }
    pub const fn value_on_x86_64(self) -> u64 { Self::VALUE_ON_X86_64[self as usize] }
    pub const fn purpose(self) -> &'static str { Self::PURPOSE[self as usize] }
    pub const fn hits(self) -> StatisticId { Self::HITS[self as usize] }
